corpus_block("test-guides.R: guide_none() can be used in non-position scales", {
  skip_on_cran()
  .plot("test-guides.R: guide_none() can be used in non-position scales #1", p <- ggplot(mpg, aes(cty, hwy, colour = class)) +
      geom_point() +
      scale_color_discrete(guide = guide_none()))
  built <- ggplot_build(p)
  .plot("test-guides.R: guide_none() can be used in non-position scales #2", plot <- built@plot)
  guides <- guides_list(plot@guides)
  guides <- guides$build(
      plot@scales,
      plot@layers,
      plot@labels
    )
})

