corpus_block("test-guides.R: guides title and text are positioned correctly", {
  skip_on_cran()
  df <- data_frame(x = 1:3, y = 1:3)
  .plot("test-guides.R: guides title and text are positioned correctly #1", p <- ggplot(df, aes(x, y, color = factor(x), fill = y)) +
      geom_point(shape = 21) +
      # setting the order explicitly removes the risk for failed doppelgangers
      # due to legends switching order
      guides(color = guide_legend(order = 2),
             fill = guide_colorbar(order = 1)) +
      theme_test())
  .plot("test-guides.R: guides title and text are positioned correctly #2", p + scale_color_discrete(name = "the\ndiscrete\ncolorscale") + scale_fill_continuous(name = "the\ncontinuous\ncolorscale"))
  .plot("test-guides.R: guides title and text are positioned correctly #3", p + theme(legend.title = element_text(margin = margin(b = 1, unit = "cm"))))
  .plot("test-guides.R: guides title and text are positioned correctly #4", p + theme(legend.text = element_text(margin = margin(l = 1, unit = "cm"))))
  df <- data_frame(x = c(1, 10, 100))
  .plot("test-guides.R: guides title and text are positioned correctly #5", p <- ggplot(df, aes(x, x, color = x, size = x)) +
      geom_point() +
      # setting the order explicitly removes the risk for failed doppelgangers
      # due to legends switching order
      guides(shape = guide_legend(order = 1),
             color = guide_colorbar(order = 2)) +
      theme_test())
  .plot("test-guides.R: guides title and text are positioned correctly #6", p + theme(legend.title = element_text(hjust = 0.5, margin = margin(t = 30, b = 5.5)), 
      legend.text = element_text(hjust = 1, margin = margin(l = 10.5, t = 10, b = 10))))
  df <- data_frame(x = c(5, 10, 15))
  .plot("test-guides.R: guides title and text are positioned correctly #7", p <- ggplot(df, aes(x, x, color = x, fill = 15 - x)) +
      geom_point(shape = 21, size = 5, stroke = 3) +
      scale_colour_continuous(
        name = "value",
        guide = guide_colorbar(
          theme = theme(
            legend.title = element_text(size = 11, angle = 0, hjust = 0.5, vjust = 1),
            legend.text = element_text(size = 0.8 * 11, angle = 270, hjust = 0.5, vjust = 1)
          ),
          order = 2 # set guide order to keep visual test stable
        )
      ) +
      scale_fill_continuous(
        breaks = c(5, 10, 15),
        limits = c(5, 15),
        labels = paste("long", c(5, 10, 15)),
        name = "fill value",
        guide = guide_legend(
          direction = "horizontal",
          theme = theme(
            legend.title.position = "top",
            legend.text.position = "bottom",
            legend.title = element_text(size = 11, angle = 180, hjust = 0, vjust = 1),
            legend.text = element_text(size = 0.8 * 11, angle = 90, hjust = 1, vjust = 0.5)
          ),
          order = 1
        )
      ))
  .plot("test-guides.R: guides title and text are positioned correctly #8", p <- ggplot(data.frame(x = 1:2)) +
      aes(x, x, colour = factor(x), fill = factor(x), shape = factor(x), alpha = x) +
      geom_point() +
      scale_alpha(breaks = 1:2) +
      guides(
        colour = guide_legend(
          "colour title with hjust = 0", order = 1,
          theme = theme(legend.title = element_text(hjust = 0))
        ),
        fill   = guide_legend(
          "fill title with hjust = 1", order = 2,
          theme = theme(
            legend.title = element_text(hjust = 1),
            legend.title.position = "bottom"
          ),
          override.aes = list(shape = 21)
        ),
        alpha  = guide_legend(
